KG42.register("rules-4475919951a53d2bff625742",{"id":"28-multiclass_prosumer_preferences::v141-c-R006","paper":"28-multiclass_prosumer_preferences","record":{"rule_id":"v141-c-R006","mechanism_id":"v141-a-M01","name":"Energy-trade execution","process_stage":"activation","market_meaning":"The local allocation solution supplies optimal current-interval renewable and battery power outputs that prosumers implement as lower level controller references for their energy sources. Scope: Real-time receding-horizon implementation of multiclass energy management for distribution-network prosumers; implementation uses the optimal powers for the current trading interval. The P2P platform coordinates energy trading between subscribed prosumers and the wholesale electricity market, with a platform agent acting as auctioneer. Scope: The proposed multiclass P2P platform for distribution-network prosumers and its wholesale electricity market interface. Small-scale prosumers are permitted to trade energy with one another and with the wholesale market. Scope: Small-scale prosumer energy trading through the proposed P2P platform. Green energy is permitted to be sold as grid energy. Scope: The IEEE European Low Voltage Test Feeder demonstration and its green-energy class. Condition: Green energy is traded at a premium in this demonstration.","independence_rationale":"Relations governed by the approved function execution.energy_trade under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.local","coordination.local_operator","execution.energy_trade"],"E":[{"edge_id":"v141-c-R006-E001","source":"clearing.local","target":"execution.energy_trade","type":"links","constraint_ids":["v141-c-R006-C001"],"evidence_ids":["v141-b-G01-E31","v141-b-g01-E08"]},{"edge_id":"v141-c-R006-E002","source":"coordination.local_operator","target":"execution.energy_trade","type":"links","constraint_ids":["v141-c-R006-C002"],"evidence_ids":["v141-b-g01-E01","v141-b-g01-E07"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Real-time receding-horizon implementation of multiclass energy management for distribution-network prosumers; implementation uses the optimal powers for the current trading interval. | Small-scale prosumer energy trading through the proposed P2P platform. | The IEEE European Low Voltage Test Feeder demonstration and its green-energy class. | The proposed multiclass P2P platform for distribution-network prosumers and its wholesale electricity market interface.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-G01-E31","v141-b-G01-E36","v141-b-g01-E01","v141-b-g01-E07","v141-b-g01-E08","v141-b-g02-e027"]},"x":[{"variable_id":"v141-c-R006-X001","symbol":"y_{ig}^{*(t_0)}","meaning":"Optimal current-interval renewable output power assigned to grid energy by prosumer i, used as a lower-level controller reference for its energy sources.","kind":"operational","domain":"nonnegative real average power","unit":null,"indices":["i \\in \\mathcal{N}","t_0 (current trading interval)"],"evidence_ids":["v141-b-G01-E31","v141-b-G01-E21"]},{"variable_id":"v141-c-R006-X002","symbol":"y_{ik}^{*(t_0)}","meaning":"Optimal current-interval renewable output power of energy class k for prosumer i, used as a lower-level controller reference for its energy sources.","kind":"operational","domain":"nonnegative real average power","unit":null,"indices":["i \\in \\mathcal{N}","k \\in \\mathcal{K}","t_0 (current trading interval)"],"evidence_ids":["v141-b-G01-E31","v141-b-G01-E21"]},{"variable_id":"v141-c-R006-X003","symbol":"b_{ig}^{*(t_0)}","meaning":"Optimal current-interval battery output power assigned to grid energy by prosumer i, used as a lower-level controller reference for its energy sources.","kind":"operational","domain":"real average battery output power","unit":null,"indices":["i \\in \\mathcal{N}","t_0 (current trading interval)"],"evidence_ids":["v141-b-G01-E31","v141-b-G01-E26"]},{"variable_id":"v141-c-R006-X004","symbol":"b_{ik}^{*(t_0)}","meaning":"Optimal current-interval battery output power assigned to energy class k by prosumer i, used as a lower-level controller reference for its energy sources.","kind":"operational","domain":"real average battery output power","unit":null,"indices":["i \\in \\mathcal{N}","k \\in \\mathcal{K}","t_0 (current trading interval)"],"evidence_ids":["v141-b-G01-E31","v141-b-G01-E26"]},{"variable_id":"v141-c-R006-X005","symbol":"b_{ikg}^{*(t_0)}","meaning":"Optimal current-interval amount of class k energy stored as grid energy by prosumer i, used as a lower-level controller reference for its energy sources.","kind":"operational","domain":"nonnegative for k \\in \\mathcal{K}_g and zero for k \\in \\mathcal{K}\\setminus\\mathcal{K}_g","unit":null,"indices":["i \\in \\mathcal{N}","k \\in \\mathcal{K}","t_0 (current trading interval)"],"evidence_ids":["v141-b-G01-E31","v141-b-G01-E25"]}],"theta":[],"phi":[{"constraint_id":"v141-c-R006-C001","kind":"procedural","role":"core","statement":"The local allocation solution supplies optimal current-interval renewable and battery power outputs that prosumers implement as lower level controller references for their energy sources. Scope: Real-time receding-horizon implementation of multiclass energy management for distribution-network prosumers; implementation uses the optimal powers for the current trading interval.","expression":"\\forall i\\in\\mathcal{N}:\\quad \\left(y_{ig}^{*(t_0)},\\, (y_{ik}^{*(t_0)})_{k\\in\\mathcal{K}},\\, b_{ig}^{*(t_0)},\\, (b_{ik}^{*(t_0)})_{k\\in\\mathcal{K}},\\, (b_{ikg}^{*(t_0)})_{k\\in\\mathcal{K}}\\right)\\ \\text{are used as lower-level controller references for prosumer }i\\text{'s energy sources at }t_0.","formalization_origin":"source","template_id":null,"members":["clearing.local","execution.energy_trade"],"variable_refs":["v141-c-R006-X001","v141-c-R006-X002","v141-c-R006-X003","v141-c-R006-X004","v141-c-R006-X005"],"parameter_refs":[],"evidence_ids":["v141-b-G01-E31","v141-b-g01-E08"]},{"constraint_id":"v141-c-R006-C002","kind":"procedural","role":"core","statement":"The P2P platform coordinates energy trading between subscribed prosumers and the wholesale electricity market, with a platform agent acting as auctioneer. Scope: The proposed multiclass P2P platform for distribution-network prosumers and its wholesale electricity market interface.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E01","v141-b-g01-E07"]},{"constraint_id":"v141-c-R006-C003","kind":"procedural","role":"core","statement":"Small-scale prosumers are permitted to trade energy with one another and with the wholesale market. Scope: Small-scale prosumer energy trading through the proposed P2P platform.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-G01-E36"]},{"constraint_id":"v141-c-R006-C004","kind":"procedural","role":"core","statement":"Green energy is permitted to be sold as grid energy. Scope: The IEEE European Low Voltage Test Feeder demonstration and its green-energy class. Condition: Green energy is traded at a premium in this demonstration.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e027"]},{"constraint_id":"v141-c-R006-C005","kind":"procedural","role":"supporting","statement":"The MPC time horizon recedes by one step, t_0 \\leftarrow t_0 + 1, for the next trading interval.","expression":"t_0 \\leftarrow t_0 + 1 \\quad \\text{for the next trading interval}","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-G01-E31"]}],"pi":[{"evidence_id":"v141-b-G01-E31","location":{"location_id":"src-96285c344a-p05-c1r4__v141-a-M01-activation","page":5,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"( ) ( ), ( ) eac Since (20) is a convex quadratic program with afﬁne constraints, to strong duality ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Receding horizon MPC can be used to implement multi-class energy management for real-time control of the distribution network prosumers. During each wholesale market trading interval: 1) For the current trading interval, t_0, the current wholesale electricity price and updated price predictions, C_g^{(t)}, \\forall t \\in \\mathcal{T}, are obtained. Also, each prosumer, i \\in \\mathcal{N}, estimates its current SoC allocated to each energy class, s_{ig}^{(t_0)}, s_{ik}^{(t_0)}, \\forall k \\in \\mathcal{K}, and obtains updated renewable generation and load predictions, y_i^{pred(t)}, z_i^{pred(t)}, \\forall t \\in \\mathcal{T}. 2) The multi-class energy management problem (20) is solved. 3) Each prosumer, i \\in \\mathcal{N}, implements the optimal renewable output powers, y_{ig}^{*(t_0)}, y_{ik}^{*(t_0)}, \\forall k \\in \\mathcal{K}, and battery output powers, b_{ig}^{*(t_0)}, b_{ik}^{*(t_0)}, b_{ikg}^{*(t_0)}, \\forall k \\in \\mathcal{K}, obtained for the current trading interval, t_0, by using them as lower level controller references for their energy sources. 4) The MPC time horizon recedes by a step, t_0 \\leftarrow t_0 + 1, for the next trading interval."},{"evidence_id":"v141-b-G01-E36","location":{"location_id":"src-96285c344a-p03-c2r1__v141-a-M01-participation","page":3,"printed_page":null,"section":"II. Principle of Operation","anchor_text":"PEER-TO-PEER ENERGY TRADING DRIVEN 4007 wholesale market without a retail supplier. However, retail ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"exception"},"source_text":"The proposed P2P energy market platform allows small-scale prosumers to trade energy with one another, and with the wholesale market, rather than relying on a traditional retail supplier. However, retail suppliers could still have an important role, providing services such as invoicing, real-time metering and local energy management [35]. Also, small-scale prosumers may not wish to be exposed to fluctuating wholesale energy prices. Prosumers could contract with retail suppliers to obtain predictable energy prices, and then their supplier could act on their behalf within the P2P platform based on their energy preferences."},{"evidence_id":"v141-b-g01-E01","location":{"location_id":"src-96285c344a-p01-c1r2__v141-a-M01-participation","page":1,"printed_page":null,"section":"Abstract","anchor_text":"platform based on the new concept of multiclass energy manage so ment, to coordinate trading between","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"This paper proposes a peer-to-peer energy market platform based on the new concept of multiclass energy management, to coordinate trading between prosumers with heterogeneous (i.e., beyond purely financial) preferences. The proposed peer-to-peer energy market platform coordinates trading between subscribed prosumers and the wholesale electricity market, to minimize costs associated with losses and battery depreciation, while providing added value by accounting for the prosumers’ individual preferences for the source/destination of the energy they consume/produce."},{"evidence_id":"v141-b-g01-E07","location":{"location_id":"src-96285c344a-p02-c2r4__v141-a-M01-participation","page":2,"printed_page":null,"section":"II. Principle of Operation","anchor_text":"y gy The proposed P2P market platform still provides value to these prosumers, by allowing them to t","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"A platform agent is introduced to act as an auctioneer and to allow energy trading between the prosumers and the wholesale electricity market. The platform agent sets the price of each energy class in the distribution network. A block diagram of the proposed P2P energy market platform is shown in Fig. 2."},{"evidence_id":"v141-b-g01-E08","location":{"location_id":"src-96285c344a-p03-c1r2__v141-a-M01-coordination","page":3,"printed_page":null,"section":"II. Principle of Operation","anchor_text":"Fig. 2. A block diagram of the proposed P2P energy market platform. Distributed price-directed optim","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Distributed price-directed optimisation parallelises the multi-class energy management problem. At each wholesale market trading interval, the prosumers solve local optimisation sub-problems to schedule their renewable sources and battery energy storage systems, considering their generation and load predictions and the price of each class of energy. The platform agent adjusts the energy class prices, considering the prosumer energy demands, the wholesale energy price, wholesale price predictions and expected losses. Iteratively, the prosumers and platform agent reach agreement on a schedule of social welfare maximising power flows."},{"evidence_id":"v141-b-g02-e027","location":{"location_id":"src-96285c344a-p06-c2r3__v141-a-M01-participation","page":6,"printed_page":null,"section":"V. Results","anchor_text":"and average resistance between the prosumers and main grid of Rg = 0.084Ω are used. t.) There are th","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"example"},"source_text":"The operation of the proposed P2P energy market platform based on multi-class energy management was verified using the IEEE European Low Voltage Test Feeder [42], with 55 prosumers. ... There are three types of prosumers in the distribution network, ‘green prosumers’, ‘philanthropic prosumers’ and ‘low-income households’. Based on their preferences, three energy classes are introduced; ‘grid energy’, ‘green energy’ and ‘subsidised energy’. Grid energy, is traded with the wholesale market at five minute trading intervals through the platform agent. Green energy is traded at a premium, so it is allowed to be substituted for and stored/sold as grid energy. Only low-income households are allowed to use subsidised energy."},{"evidence_id":"v141-b-G01-E21","location":{"location_id":"src-96285c344a-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 34, NO. 5, SEPTEMBER 2019 reserved for low-income household","equation_id":"(9)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"For prosumer i \\in \\mathcal{N}, let y_i^{pred(t)} be the predicted generation capacity at interval t. \\sum_{k \\in \\mathcal{K}} y_{ik}^{(t)} + y_{ig}^{(t)} = y_i^{pred(t)}, \\forall t \\in \\mathcal{T}. \\quad 0 \\le y_{ig}^{(t)}, 0 \\le y_{ik}^{(t)}, \\forall k \\in \\mathcal{K}, \\forall t \\in \\mathcal{T}."},{"evidence_id":"v141-b-G01-E25","location":{"location_id":"src-96285c344a-p05-c1r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"MORSTYN AND MCCULLOCH: MULTICLASS ENERGY MANAGEMENT FOR PEER-TO-P energy classes that can be substit","equation_id":"(15)-(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The following constraints are introduced to restrict the energy classes that can be substituted and stored as grid energy. 0 \\le b_{ikg}^{(t)}, \\forall k \\in \\mathcal{K}_g, \\forall t \\in \\mathcal{T}, \\quad b_{ikg}^{(t)} = 0, \\forall k \\in \\mathcal{K} \\setminus \\mathcal{K}_g, \\forall t \\in \\mathcal{T}."},{"evidence_id":"v141-b-G01-E26","location":{"location_id":"src-96285c344a-p05-c1r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"MORSTYN AND MCCULLOCH: MULTICLASS ENERGY MANAGEMENT FOR PEER-TO-P energy classes that can be substit","equation_id":"(17)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The battery also has output power limits. Let B_{ci}^{max} be the maximum charging power and B_{di}^{max} be the maximum discharging power. The battery output power constraints for prosumer i are given by, -B_{ci}^{max} \\le \\sum_{k \\in \\mathcal{K}} b_{ik}^{(t)} + b_{ig}^{(t)} \\le B_{di}^{max}, \\forall t \\in \\mathcal{T}."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":"The formalized activation assignment uses optimal output variables and the time index t_0; it introduces no fixed numeric or symbolic input parameter. Wholesale prices, price predictions, SoC estimates, and generation/load predictions appear in the preceding solve step of the source procedure, not in the step-3 implementation assignment or the step-4 horizon update formalized here."},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-activation","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing"],"extras":{"decision_anchor":"execution.energy_trade","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E08","quote":"Iteratively, the prosumers and platform agent reach agreement on a schedule of social welfare maximising power flows."},{"evidence_id":"v141-b-G01-E31","quote":"2) The multi-class energy management problem (20) is solved. 3) Each prosumer, i \\in \\mathcal{N}, implements the optimal renewable output powers, y_{ig}^{*(t_0)}, y_{ik}^{*(t_0)}, \\forall k \\in \\mathcal{K}, and battery output powers, b_{ig}^{*(t_0)}, b_{ik}^{*(t_0)}, b_{ikg}^{*(t_0)}, \\forall k \\in \\mathcal{K}, obtained for the current trading interval, t_0, by using them as lower level controller references for their energy sources."}],[{"evidence_id":"v141-b-g01-E01","quote":"The proposed peer-to-peer energy market platform coordinates trading between subscribed prosumers and the wholesale electricity market"},{"evidence_id":"v141-b-g01-E07","quote":"A platform agent is introduced to act as an auctioneer and to allow energy trading between the prosumers and the wholesale electricity market."}],[{"evidence_id":"v141-b-G01-E36","quote":"The proposed P2P energy market platform allows small-scale prosumers to trade energy with one another, and with the wholesale market, rather than relying on a traditional retail supplier."}],[{"evidence_id":"v141-b-g02-e027","quote":"Green energy is traded at a premium, so it is allowed to be substituted for and stored/sold as grid energy."}]],"C2_formalization":{"graph_sha256":"c74907a807b1e8848897a32c1e6f9bc079c84084a0969abf5bb3dfd03d8a0524","applicability":"formalized","reason":"The source gives an explicit current-interval activation procedure: after solving the multiclass management problem, each prosumer uses the optimal renewable and battery output powers for the current trading interval as lower-level controller references, and then the MPC horizon recedes. The activation assignment is formalized under C001 and the source-supported horizon update is added as C005. C002-C004 remain non-formalized procedural/institutional statements because the supplied text does not express them as equations. Evidence remains unreviewed under the experiment policy; no independent source audit is claimed.","bindings":[{"object_id":"v141-c-R006-X001","node_ids":["clearing.local","execution.energy_trade"],"edge_ids":["v141-c-R006-E001"],"rationale":"The optimal grid-class renewable output is obtained from the local clearing solution and then applied by execution as a lower-level controller reference."},{"object_id":"v141-c-R006-X002","node_ids":["clearing.local","execution.energy_trade"],"edge_ids":["v141-c-R006-E001"],"rationale":"The optimal non-grid-class renewable outputs are obtained from the local clearing solution and then applied by execution as lower-level controller references."},{"object_id":"v141-c-R006-X003","node_ids":["clearing.local","execution.energy_trade"],"edge_ids":["v141-c-R006-E001"],"rationale":"The optimal grid-class battery output is obtained from the local clearing solution and then applied by execution as a lower-level controller reference."},{"object_id":"v141-c-R006-X004","node_ids":["clearing.local","execution.energy_trade"],"edge_ids":["v141-c-R006-E001"],"rationale":"The optimal non-grid-class battery outputs are obtained from the local clearing solution and then applied by execution as lower-level controller references."},{"object_id":"v141-c-R006-X005","node_ids":["clearing.local","execution.energy_trade"],"edge_ids":["v141-c-R006-E001"],"rationale":"The optimal grid-energy storage quantities by class are obtained from the local clearing solution and then applied by execution as lower-level controller references."},{"object_id":"v141-c-R006-C001","node_ids":["clearing.local","execution.energy_trade"],"edge_ids":["v141-c-R006-E001"],"rationale":"This is the core edge from local clearing to energy-trade execution: optimal current-interval outputs are implemented as controller references."},{"object_id":"v141-c-R006-C002","node_ids":["coordination.local_operator","execution.energy_trade"],"edge_ids":["v141-c-R006-E002"],"rationale":"The platform-agent auctioneer/coordination role links to execution via the frozen coordination-to-execution edge."},{"object_id":"v141-c-R006-C003","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The permission for small-scale prosumers to trade is represented at the execution node; no additional frozen graph edge represents this permission."},{"object_id":"v141-c-R006-C004","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The green-energy demonstration permission is represented at the execution node; no additional frozen graph edge represents this conditional product permission."},{"object_id":"v141-c-R006-C005","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The MPC horizon update belongs to the activation/execution timing step represented by execution.energy_trade."}],"revision_requests":[]}},"quarantined_references":[]}});
